flow.python:
# D20 · Part 0~7 · 오늘의 흐름 전체: 세 시스템 합성 → MOS · 자동 지표 → 마스터링 → 목표 판정 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6 scipy==1.17.1
# 실행: python d20_flow.py   (인터넷 · GPU · 마이크 불필요 · UTMOS · Whisper · Chatterbox 대신 장난감 모델)
#   잡음 수준이 다른 세 장난감 시스템을 사람 점수(MOS 신뢰구간)와 자동 점수로 견주고, 1등을 마스터링해 목표를 판정 (장난감 모델)
import re
import numpy as np
from scipy import stats

def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")

SR = 24000
HANGUL = re.compile(r"[가-힣]")


def generate(text: str, exaggeration: float = 0.5, cfg_weight: float = 0.5, seed: int = 0, ref: dict = None) -> np.ndarray:
    """Chatterbox 흉내: 손잡이 -> 말 빠르기 · 음높이 폭 · 세기 변화 (신경망 대신 규칙 · 사인파)"""
    rng = np.random.default_rng(seed)
    n_syl = max(len(HANGUL.findall(text)), 1)
    rate = 3.5 + 2.5 * cfg_weight                              # 음절/초: cfg_weight가 낮을수록 천천히 또박또박
    sec = n_syl / rate + 0.4
    t = np.arange(int(sec * SR)) / SR
    base = 200.0 if ref is None else ref["f0"]                  # 참고 음성이 있으면 그 목소리 높이 · 표현 폭을 따라간다
    depth = 1.0 if ref is None else ref["depth"]
    st = ((2 + 10 * exaggeration) * depth / 2) * np.sin(2 * np.pi * (rate / 2) * t + rng.uniform(0, 2 * np.pi))   # 반음 단위 억양
    if text.rstrip().endswith("?"):
        st += 4 * np.clip((t - (sec - 0.8)) / 0.6, 0, 1)         # 물음표: 끝이 올라감
    if text.rstrip().endswith("!"):
        st += 2                                                  # 느낌표: 전체가 높아짐
    f0 = base * 2 ** (st / 12)
    amp = 0.3 * (1 + 0.6 * exaggeration * np.sin(2 * np.pi * rate * t)) * (t < sec - 0.2)   # 끝 0.2초는 쉼
    return (amp * np.sin(2 * np.pi * np.cumsum(f0) / SR)).astype(np.float32)


def frame_f0(y: np.ndarray, sr: int = SR, frame_sec: float = 0.05):
    """50 ms 창마다 0 교차 시각으로 음높이(Hz)를 잰다. 소리 없는 창은 nan"""
    n = int(frame_sec * sr)
    hop = n // 2
    out = []
    for a in range(0, len(y) - n, hop):
        w = y[a:a + n].astype(np.float64)
        idx = np.where((w[:-1] < 0) & (w[1:] >= 0))[0]
        if np.abs(w).max() < 0.02 or len(idx) < 3:
            out.append(np.nan)
            continue
        ts = idx + (-w[idx]) / (w[idx + 1] - w[idx])               # 0을 지나는 시각 (샘플 사이를 직선으로 보간)
        out.append((len(ts) - 1) / (ts[-1] - ts[0]) * sr)
    return np.array(out), hop


def prosody(y: np.ndarray, sr: int = SR, text: str = None) -> dict:
    """운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초"""
    f0, hop = frame_f0(y, sr)
    v = f0[~np.isnan(f0)]
    st = 12 * np.log2(v / np.median(v))                            # 중앙값 대비 반음
    rms = np.array([np.sqrt(np.mean(y[a:a + hop * 2] ** 2)) for a in range(0, len(y) - hop * 2, hop)])
    db = 20 * np.log10(rms + 1e-6)
    loud = db[db > db.max() - 35]
    speech_sec = max(float((db > db.max() - 35).sum()) * hop / sr, 1e-3)
    out = dict(pitch_hz=float(np.median(v)), range_st=float(np.percentile(st, 90) - np.percentile(st, 10)),
               energy_db=float(loud.std()), silence=float(1 - speech_sec / (len(y) / sr)))
    out["syl_per_sec"] = len(HANGUL.findall(text)) / speech_sec if text else float("nan")
    return out


def tail_semitone(y: np.ndarray, sr: int = SR) -> float:
    """끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)"""
    f0, hop = frame_f0(y, sr)
    t = np.arange(len(f0)) * hop / sr
    ok = ~np.isnan(f0)
    end = t[ok][-1]
    return float(np.mean(12 * np.log2(f0[ok & (t > end - 0.6)] / np.median(f0[ok]))))

def edit_distance(a, b) -> int:
    """레벤슈타인 편집 거리 (글자 · 낱말 열 모두 가능)"""
    prev = list(range(len(b) + 1))
    for i, x in enumerate(a, 1):
        cur = [i]
        for j, y in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (x != y)))
        prev = cur
    return prev[-1]


def cer(ref: str, hyp: str) -> float:
    """글자 오류율(%) = 편집 거리 / 정답 글자 수 x 100"""
    return 100 * edit_distance(ref, hyp) / max(len(ref), 1)

WM_REL, HOLD = 0.1, 4          # 워터마크 세기 = 소리 크기(rms)의 10% · 같은 값을 4샘플씩 유지(낮은 소리 쪽에 모여 전화 음질에도 남음)


def wm_key(n: int, secret: int = 1234) -> np.ndarray:
    """비밀 값에서 만든 +1/-1 열 (xorshift32). 같은 비밀이면 같은 열 -> 검출기가 알아본다"""
    x, bits = secret & 0xFFFFFFFF, np.empty(-(-n // HOLD))
    for i in range(len(bits)):
        x ^= (x << 13) & 0xFFFFFFFF
        x ^= x >> 17
        x ^= (x << 5) & 0xFFFFFFFF
        bits[i] = 1.0 if x & 1 else -1.0
    return np.repeat(bits, HOLD)[:n]


def rms(y: np.ndarray) -> float:
    return float(np.sqrt(np.mean(np.asarray(y, dtype=np.float64) ** 2)) + 1e-12)


def apply_watermark(y: np.ndarray) -> np.ndarray:
    """소리에 비밀 열을 작게 더한다 (Perth 워터마커의 아이디어만 흉내)"""
    return (y + WM_REL * rms(y) * wm_key(len(y))).astype(np.float32)


def get_watermark(y: np.ndarray) -> float:
    """비밀 열과 얼마나 닮았나 0~1 (소리 크기와 무관). 0.5 이상이면 '워터마크 있음'. 시작 위치가 어긋나면 못 찾는다"""
    return float(np.clip(np.mean(y * wm_key(len(y))) / (WM_REL * rms(y)), 0, 1))


def add_noise(y: np.ndarray, snr_db: float, seed: int = 0) -> np.ndarray:
    """신호 대 잡음비가 snr_db가 되도록 흰 잡음을 더한다"""
    n = np.random.default_rng(seed).standard_normal(len(y))
    p_sig, p_noise = np.mean(y.astype(np.float64) ** 2), np.mean(n ** 2)
    return (y + n * np.sqrt(p_sig / (p_noise * 10 ** (snr_db / 10)))).astype(np.float32)

SYSTEM_SNR = {"A": 40, "B": 25, "C": 10}                 # 시스템마다 섞인 잡음 수준(dB): 클수록 깨끗
SENTS = ["오늘은 사 주차 마지막 날입니다", "음성 합성의 원리부터 배웠습니다", "직접 만든 소리를 평가합니다", "끝까지 함께해 주셔서 고맙습니다"]


def make_sample(system: str, k: int) -> np.ndarray:
    return add_noise(generate(SENTS[k], exaggeration=0.4, seed=20 + k), SYSTEM_SNR[system], seed=k)


def snr_estimate(y: np.ndarray) -> float:
    """끝 쉼 구간의 잡음 전력 대비 말하는 구간 전력 (dB)"""
    quiet = np.mean(y[-int(0.1 * SR):].astype(np.float64) ** 2)
    loud = np.mean(y[:-int(0.2 * SR)].astype(np.float64) ** 2)
    return float(10 * np.log10(loud / quiet))


def auto_mos(y: np.ndarray) -> float:
    """UTMOS 흉내: 잡음이 적을수록 높은 1~5 점수 (진짜 UTMOS는 학습한 신경망)"""
    return float(1 + 4 * np.clip((snr_estimate(y) - 5) / 35, 0, 1))


def corrupt(text: str, p: float, seed: int) -> str:
    """받아쓰기 대신: 글자를 확률 p로 틀리게 (잡음이 많을수록 p가 큼)"""
    rng = np.random.default_rng(seed)
    return "".join("ㅇ" if rng.random() < p else c for c in text)


def pearson(a, b) -> float:
    return float(np.corrcoef(a, b)[0, 1])

def mos_ci(scores, conf: float = 0.95):
    """평균 점수(MOS)와 95% 신뢰구간 반폭 = t(0.975, n-1) x 표준편차 / sqrt(n)"""
    x = np.asarray(scores, dtype=float)
    n = len(x)
    half = stats.t.ppf((1 + conf) / 2, n - 1) * x.std(ddof=1) / np.sqrt(n)
    return float(x.mean()), float(half), n


def virtual_class(n_raters: int = 15, seed: int = 7) -> dict:
    """가상 반: 평가자 n명이 시스템마다 1~5점 (평가자마다 후한 정도가 다름)"""
    r = np.random.default_rng(seed)
    out = {"A": [], "B": [], "C": []}
    for _ in range(n_raters):
        bias = r.normal(0, 0.4)
        for s, mu in {"A": 4.3, "B": 3.6, "C": 2.9}.items():
            out[s].append(int(np.clip(round(mu + bias + r.normal(0, 0.6)), 1, 5)))
    return out


def lufs(y: np.ndarray) -> float:
    """음량(LUFS) 단순 측정: -0.691 + 10 x log10(평균 제곱). 진짜 LUFS의 K 가중 필터 · 게이팅은 생략"""
    return float(-0.691 + 10 * np.log10(np.mean(y.astype(np.float64) ** 2) + 1e-12))


def peak_db(y: np.ndarray) -> float:
    return float(20 * np.log10(np.max(np.abs(y)) + 1e-9))


def silence(sec: float) -> np.ndarray:
    return np.zeros(int(sec * SR), np.float32)


def master(y: np.ndarray, target_lufs: float, peak_max_db: float = -1.0):
    """음량을 목표 LUFS에 맞추고, 피크가 상한을 넘으면 전체를 조금 줄인다 (간단한 리미터)"""
    y = y * 10 ** ((target_lufs - lufs(y)) / 20)
    if peak_db(y) > peak_max_db:
        y = y * 10 ** ((peak_max_db - peak_db(y)) / 20)
    y = y.astype(np.float32)
    return y, lufs(y), peak_db(y)

MODE_LUFS = {"audiobook": -18.0, "announce": -16.0}
GOALS = [("게이트 통과율", lambda r: r["gate_rate"] >= 0.8, "≥ 0.8"),
         ("음량", lambda r: abs(r["lufs"] - MODE_LUFS[r["mode"]]) <= 1.0, "목표 ± 1 LU"),
         ("피크", lambda r: r["peak"] <= -1.0 + 1e-3, "≤ -1 dBFS"),
         ("워터마크", lambda r: r["wm"] >= 0.5, "검출 1"),
         ("평균 CER", lambda r: r["mean_cer"] <= 0.10, "≤ 0.10")]


CLASS = virtual_class()                                                     # 1) 사람 평가 (가상 반 15명)
mos = {s: mos_ci(v) for s, v in CLASS.items()}
auto = {s: float(np.mean([auto_mos(make_sample(s, k)) for k in range(len(SENTS))])) for s in "ABC"}   # 2) 자동 점수
print({s: f"MOS {mos[s][0]:.2f}±{mos[s][1]:.2f} · 자동 {auto[s]:.2f}" for s in "ABC"})
best = max(mos, key=lambda s: mos[s][0])
program = apply_watermark(np.concatenate([make_sample(best, k) for k in range(len(SENTS))]))   # 3) 1등으로 프로그램 만들기
y, lu, pk = master(program, -16.0)                                          # 4) 마스터링
cers = [cer(SENTS[k], corrupt(SENTS[k], 0.02, seed=k)) / 100 for k in range(len(SENTS))]
report = dict(mode="announce", gate_rate=1.0, lufs=lu, peak=pk, wm=get_watermark(y), mean_cer=float(np.mean(cers)))
verdict = {g: f(report) for g, f, _ in GOALS}                               # 5) 목표 판정
print("목표 판정:", verdict)
check(best == "A" and auto["A"] > auto["B"] > auto["C"] and mos["A"][0] > mos["C"][0] and all(verdict.values()), "1등은 A이고 목표를 모두 통과해야 해요")

flow.typescript:
// D20 · Part 0~7 · 오늘의 흐름 전체: 세 시스템 합성 → MOS · 자동 지표 → 마스터링 → 목표 판정 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d20_flow.ts
//   잡음 수준이 다른 세 장난감 시스템을 사람 점수(MOS 신뢰구간)와 자동 점수로 견주고, 1등을 마스터링해 목표를 판정 (장난감 모델)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const SR = 24000;
const HANGUL = /[가-힣]/g;

function generate(text: string, exaggeration = 0.5, cfgWeight = 0.5, seed = 0, ref: { f0: number; depth: number } | null = null): Float32Array {
  // Chatterbox 흉내: 손잡이 -> 말 빠르기 · 음높이 폭 · 세기 변화 (신경망 대신 규칙 · 사인파)
  const r = rng(seed);
  const nSyl = Math.max((text.match(HANGUL) ?? []).length, 1);
  const rate = 3.5 + 2.5 * cfgWeight; // 음절/초: cfg_weight가 낮을수록 천천히 또박또박
  const sec = nSyl / rate + 0.4;
  const base = ref ? ref.f0 : 200; // 참고 음성이 있으면 그 목소리 높이 · 표현 폭을 따라간다
  const depth = ref ? ref.depth : 1;
  const phi = r() * 2 * Math.PI;
  const q = text.trimEnd().endsWith("?");
  const ex = text.trimEnd().endsWith("!");
  const y = new Float32Array(Math.floor(sec * SR));
  let phase = 0;
  for (let i = 0; i < y.length; i++) {
    const t = i / SR;
    let st = (((2 + 10 * exaggeration) * depth) / 2) * Math.sin(2 * Math.PI * (rate / 2) * t + phi); // 반음 단위 억양
    if (q) st += 4 * Math.min(1, Math.max(0, (t - (sec - 0.8)) / 0.6)); // 물음표: 끝이 올라감
    if (ex) st += 2; // 느낌표: 전체가 높아짐
    phase += (2 * Math.PI * base * 2 ** (st / 12)) / SR;
    const amp = 0.3 * (1 + 0.6 * exaggeration * Math.sin(2 * Math.PI * rate * t)) * (t < sec - 0.2 ? 1 : 0); // 끝 0.2초는 쉼
    y[i] = amp * Math.sin(phase);
  }
  return y;
}

function frameF0(y: Float32Array, sr = SR, frameSec = 0.05): { f0: number[]; hop: number } {
  // 50 ms 창마다 0 교차 시각으로 음높이(Hz)를 잰다. 소리 없는 창은 NaN
  const n = Math.floor(frameSec * sr);
  const hop = Math.floor(n / 2);
  const f0: number[] = [];
  for (let a = 0; a < y.length - n; a += hop) {
    const ts: number[] = [];
    let peak = 0;
    for (let i = 0; i < n; i++) {
      peak = Math.max(peak, Math.abs(y[a + i]));
      if (i > 0 && y[a + i - 1] < 0 && y[a + i] >= 0) ts.push(i - 1 + -y[a + i - 1] / (y[a + i] - y[a + i - 1])); // 샘플 사이를 직선으로 보간
    }
    f0.push(peak < 0.02 || ts.length < 3 ? NaN : ((ts.length - 1) / (ts[ts.length - 1] - ts[0])) * sr);
  }
  return { f0, hop };
}

const median = (x: number[]): number => { const s = [...x].sort((a, b) => a - b); return s[Math.floor((s.length - 1) / 2)] / 2 + s[Math.ceil((s.length - 1) / 2)] / 2; };
const percentile = (x: number[], p: number): number => {
  const s = [...x].sort((a, b) => a - b);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
};

function prosody(y: Float32Array, sr = SR, text: string | null = null) {
  // 운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초
  const { f0, hop } = frameF0(y, sr);
  const v = f0.filter((x) => !Number.isNaN(x));
  const med = median(v);
  const st = v.map((x) => 12 * Math.log2(x / med)); // 중앙값 대비 반음
  const db: number[] = [];
  for (let a = 0; a < y.length - hop * 2; a += hop) {
    let s = 0;
    for (let i = 0; i < hop * 2; i++) s += y[a + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / (hop * 2)) + 1e-6));
  }
  const top = Math.max(...db);
  const loud = db.filter((d) => d > top - 35);
  const m = loud.reduce((a, b) => a + b, 0) / loud.length;
  const speechSec = Math.max((loud.length * hop) / sr, 1e-3);
  return {
    pitchHz: med,
    rangeSt: percentile(st, 90) - percentile(st, 10),
    energyDb: Math.sqrt(loud.reduce((a, b) => a + (b - m) ** 2, 0) / loud.length),
    silence: 1 - speechSec / (y.length / sr),
    sylPerSec: text ? (text.match(HANGUL) ?? []).length / speechSec : NaN,
  };
}

function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

function editDistance(a: string[], b: string[]): number {
  // 레벤슈타인 편집 거리 (글자 · 낱말 열 모두 가능)
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] !== b[j - 1] ? 1 : 0)));
    }
    prev = cur;
  }
  return prev[b.length];
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율(%) = 편집 거리 / 정답 글자 수 x 100
  const r = [...ref];
  return (100 * editDistance(r, [...hyp])) / Math.max(r.length, 1);
}

const WM_REL = 0.1; // 워터마크 세기 = 소리 크기(rms)의 10%
const HOLD = 4; // 같은 값을 4샘플씩 유지(낮은 소리 쪽에 모여 전화 음질에도 남음)

function wmKey(n: number, secret = 1234): Float64Array {
  // 비밀 값에서 만든 +1/-1 열 (xorshift32). 같은 비밀이면 같은 열 -> 검출기가 알아본다
  let x = secret >>> 0;
  const out = new Float64Array(n);
  for (let i = 0; i < n; i += HOLD) {
    x = (x ^ (x << 13)) >>> 0;
    x = (x ^ (x >>> 17)) >>> 0;
    x = (x ^ (x << 5)) >>> 0;
    for (let j = i; j < Math.min(i + HOLD, n); j++) out[j] = x & 1 ? 1 : -1;
  }
  return out;
}

function rms(y: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < y.length; i++) s += y[i] * y[i];
  return Math.sqrt(s / y.length) + 1e-12;
}

function applyWatermark(y: Float32Array): Float32Array {
  // 소리에 비밀 열을 작게 더한다 (Perth 워터마커의 아이디어만 흉내)
  const k = wmKey(y.length);
  const r = rms(y);
  return Float32Array.from(y, (v, i) => v + WM_REL * r * k[i]);
}

function getWatermark(y: Float32Array): number {
  // 비밀 열과 얼마나 닮았나 0~1 (소리 크기와 무관). 0.5 이상이면 '워터마크 있음'. 시작 위치가 어긋나면 못 찾는다
  const k = wmKey(y.length);
  let s = 0;
  for (let i = 0; i < y.length; i++) s += y[i] * k[i];
  return Math.min(1, Math.max(0, s / y.length / (WM_REL * rms(y))));
}

function addNoise(y: Float32Array, snrDb: number, seed = 0): Float32Array {
  // 신호 대 잡음비가 snr_db가 되도록 흰 잡음을 더한다
  const r = rng(seed);
  const n = Float64Array.from({ length: y.length }, () => gauss(r));
  const pSig = y.reduce((a, v) => a + v * v, 0) / y.length;
  const pNoise = n.reduce((a, v) => a + v * v, 0) / n.length;
  const g = Math.sqrt(pSig / (pNoise * 10 ** (snrDb / 10)));
  return Float32Array.from(y, (v, i) => v + n[i] * g);
}

const SYSTEM_SNR: Record<string, number> = { A: 40, B: 25, C: 10 }; // 시스템마다 섞인 잡음 수준(dB): 클수록 깨끗
const SENTS = ["오늘은 사 주차 마지막 날입니다", "음성 합성의 원리부터 배웠습니다", "직접 만든 소리를 평가합니다", "끝까지 함께해 주셔서 고맙습니다"];

const makeSample = (system: string, k: number): Float32Array => addNoise(generate(SENTS[k], 0.4, 0.5, 20 + k), SYSTEM_SNR[system], k);

function snrEstimate(y: Float32Array): number {
  // 끝 쉼 구간의 잡음 전력 대비 말하는 구간 전력 (dB)
  const q = Math.floor(0.1 * SR);
  const t = Math.floor(0.2 * SR);
  const quiet = y.slice(y.length - q).reduce((a, v) => a + v * v, 0) / q;
  const loud = y.slice(0, y.length - t).reduce((a, v) => a + v * v, 0) / (y.length - t);
  return 10 * Math.log10(loud / quiet);
}

// UTMOS 흉내: 잡음이 적을수록 높은 1~5 점수 (진짜 UTMOS는 학습한 신경망)
const autoMos = (y: Float32Array): number => 1 + 4 * Math.min(1, Math.max(0, (snrEstimate(y) - 5) / 35));

function corrupt(text: string, p: number, seed: number): string {
  // 받아쓰기 대신: 글자를 확률 p로 틀리게 (잡음이 많을수록 p가 큼)
  const r = rng(seed);
  return [...text].map((c) => (r() < p ? "ㅇ" : c)).join("");
}

function pearson(a: number[], b: number[]): number {
  const ma = a.reduce((x, y) => x + y, 0) / a.length;
  const mb = b.reduce((x, y) => x + y, 0) / b.length;
  let sab = 0;
  let saa = 0;
  let sbb = 0;
  a.forEach((v, i) => { sab += (v - ma) * (b[i] - mb); saa += (v - ma) ** 2; sbb += (b[i] - mb) ** 2; });
  return sab / Math.sqrt(saa * sbb);
}

const T975 = [0, 12.706, 4.303, 3.182, 2.776, 2.571, 2.447, 2.365, 2.306, 2.262, 2.228, 2.201, 2.179, 2.160, 2.145, 2.131, 2.120, 2.110, 2.101, 2.093, 2.086, 2.080, 2.074, 2.069, 2.064, 2.060, 2.056, 2.052, 2.048, 2.045, 2.042]; // t 분포 0.975 값 표 (df 1~30, 그 위는 정규분포 1.96)

function mosCi(scores: number[]): { mean: number; half: number; n: number } {
  // 평균 점수(MOS)와 95% 신뢰구간 반폭 = t(0.975, n-1) x 표준편차 / sqrt(n)
  const n = scores.length;
  const mean = scores.reduce((a, b) => a + b, 0) / n;
  const sd = Math.sqrt(scores.reduce((a, b) => a + (b - mean) ** 2, 0) / (n - 1));
  const t = n - 1 <= 30 ? T975[n - 1] : 1.96;
  return { mean, half: (t * sd) / Math.sqrt(n), n };
}

function virtualClass(nRaters = 15, seed = 7): Record<string, number[]> {
  // 가상 반: 평가자 n명이 시스템마다 1~5점 (평가자마다 후한 정도가 다름)
  const r = rng(seed);
  const out: Record<string, number[]> = { A: [], B: [], C: [] };
  for (let i = 0; i < nRaters; i++) {
    const bias = 0.4 * gauss(r);
    for (const [s, mu] of Object.entries({ A: 4.3, B: 3.6, C: 2.9 })) out[s].push(Math.min(5, Math.max(1, Math.round(mu + bias + 0.6 * gauss(r)))));
  }
  return out;
}

function lufs(y: Float32Array): number {
  // 음량(LUFS) 단순 측정: -0.691 + 10 x log10(평균 제곱). 진짜 LUFS의 K 가중 필터 · 게이팅은 생략
  return -0.691 + 10 * Math.log10(y.reduce((a, v) => a + v * v, 0) / y.length + 1e-12);
}

const peakDb = (y: Float32Array): number => 20 * Math.log10(y.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9);
const silence = (sec: number): Float32Array => new Float32Array(Math.floor(sec * SR));

function master(input: Float32Array, targetLufs: number, peakMaxDb = -1.0): { y: Float32Array; lufs: number; peak: number } {
  // 음량을 목표 LUFS에 맞추고, 피크가 상한을 넘으면 전체를 조금 줄인다 (간단한 리미터)
  let g = 10 ** ((targetLufs - lufs(input)) / 20);
  let y = Float32Array.from(input, (v) => v * g);
  if (peakDb(y) > peakMaxDb) {
    g = 10 ** ((peakMaxDb - peakDb(y)) / 20);
    y = y.map((v) => v * g);
  }
  return { y, lufs: lufs(y), peak: peakDb(y) };
}

type Rep = { name: string; mode: string; gate_rate: number; lufs: number; peak: number; wm: number; mean_cer: number };
const MODE_LUFS: Record<string, number> = { audiobook: -18.0, announce: -16.0 };
const GOALS: [string, (r: Rep) => boolean, string][] = [
  ["게이트 통과율", (r) => r.gate_rate >= 0.8, "≥ 0.8"],
  ["음량", (r) => Math.abs(r.lufs - MODE_LUFS[r.mode]) <= 1.0, "목표 ± 1 LU"],
  ["피크", (r) => r.peak <= -1.0 + 1e-3, "≤ -1 dBFS"],
  ["워터마크", (r) => r.wm >= 0.5, "검출 1"],
  ["평균 CER", (r) => r.mean_cer <= 0.1, "≤ 0.10"],
];

const CLASS = virtualClass(); // 1) 사람 평가 (가상 반 15명)
const mos: Record<string, ReturnType<typeof mosCi>> = {};
for (const [s, v] of Object.entries(CLASS)) mos[s] = mosCi(v);
const avg = (x: number[]): number => x.reduce((a, b) => a + b, 0) / x.length;
const auto: Record<string, number> = {}; // 2) 자동 점수
for (const s of ["A", "B", "C"]) auto[s] = avg(SENTS.map((_, k) => autoMos(makeSample(s, k))));
console.log(JSON.stringify(Object.fromEntries(["A", "B", "C"].map((s) => [s, `MOS ${mos[s].mean.toFixed(2)}±${mos[s].half.toFixed(2)} · 자동 ${auto[s].toFixed(2)}`]))));
const best = Object.keys(mos).reduce((a, b) => (mos[b].mean > mos[a].mean ? b : a));
const pieces = SENTS.map((_, k) => makeSample(best, k)); // 3) 1등으로 프로그램 만들기 (워터마크는 이어 붙인 전체에 한 번)
const program = new Float32Array(pieces.reduce((a, p) => a + p.length, 0));
let off = 0;
for (const p of pieces) { program.set(p, off); off += p.length; }
const m = master(applyWatermark(program), -16.0); // 4) 마스터링
const cers = SENTS.map((s, k) => cer(s, corrupt(s, 0.02, k)) / 100);
const report: Rep = { name: "flow", mode: "announce", gate_rate: 1.0, lufs: m.lufs, peak: m.peak, wm: getWatermark(m.y), mean_cer: avg(cers) };
const verdict = Object.fromEntries(GOALS.map(([g, f]) => [g, f(report)])); // 5) 목표 판정
console.log("목표 판정:", JSON.stringify(verdict));
check(best === "A" && auto["A"] > auto["B"] && auto["B"] > auto["C"] && mos["A"].mean > mos["C"].mean && Object.values(verdict).every(Boolean), "1등은 A이고 목표를 모두 통과해야 해요");

metrics.python:
# D20 · Part 1 · TTS 평가 지표 지도: 무엇을 재고 싶은가 → 어떤 지표 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d20_metrics.py   (인터넷 · GPU · 마이크 불필요)
#   MOS · CER · UTMOS · TTFA · RTF · LUFS · 화자 유사도가 각각 무엇을 재는지 표로 두고, 질문에서 지표를 고르는 함수와 CER 계산 예
def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")

def edit_distance(a, b) -> int:
    """레벤슈타인 편집 거리 (글자 · 낱말 열 모두 가능)"""
    prev = list(range(len(b) + 1))
    for i, x in enumerate(a, 1):
        cur = [i]
        for j, y in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (x != y)))
        prev = cur
    return prev[-1]


def cer(ref: str, hyp: str) -> float:
    """글자 오류율(%) = 편집 거리 / 정답 글자 수 x 100"""
    return 100 * edit_distance(ref, hyp) / max(len(ref), 1)

METRICS = {
    "MOS": dict(measures="사람이 듣기에 자연스러운가", needs_ref=False, cost="사람 평가자 필요 (비쌈)"),
    "UTMOS": dict(measures="자연스러움을 신경망이 예측", needs_ref=False, cost="자동 (싸지만 한국어 절대값 주의)"),
    "CER": dict(measures="말한 내용이 정확한가 (ASR로 되받아쓰기)", needs_ref=True, cost="자동 (ASR 필요)"),
    "TTFA": dict(measures="첫 소리까지 기다린 시간", needs_ref=False, cost="시계만 있으면 됨"),
    "RTF": dict(measures="합성 시간 / 소리 길이 (1 미만이면 실시간)", needs_ref=False, cost="시계만 있으면 됨"),
    "LUFS": dict(measures="방송 규격 음량", needs_ref=False, cost="신호만 있으면 됨"),
    "화자 유사도": dict(measures="참고 목소리와 닮았는가", needs_ref=True, cost="자동 (화자 모델 필요)"),
}
QUESTIONS = {"사람이 듣기에 자연스러운가?": "MOS", "읽어야 할 내용을 정확히 말하나?": "CER", "버튼을 누르고 얼마 만에 소리가 나나?": "TTFA",
             "방송 음량 규격에 맞나?": "LUFS", "복제한 목소리가 본인과 비슷한가?": "화자 유사도", "서버 한 대로 몇 명까지 동시에 합성할까?": "RTF"}


KEYWORDS = {"MOS": ["자연스러", "듣기"], "UTMOS": ["예측"], "CER": ["정확", "내용"], "TTFA": ["얼마 만에", "기다"],
            "RTF": ["동시에", "실시간", "서버"], "LUFS": ["음량", "방송"], "화자 유사도": ["본인", "비슷", "닮"]}


def pick_metric(question: str) -> str:
    """질문에 든 핵심 낱말이 가장 많이 겹치는 지표를 고른다"""
    return max(METRICS, key=lambda m: sum(k in question for k in KEYWORDS[m]))


for q, expected in QUESTIONS.items():
    print(f"{q:30s} -> {expected}")
ok_pick = all(pick_metric(q) == m for q, m in QUESTIONS.items() if m != "UTMOS")
print("CER 예:", round(cer("안녕하세요 반갑습니다", "안녕하세여 반갑습니다"), 1), "% (글자 1개 틀림 / 정답 11글자)")
check(ok_pick and abs(cer("안녕하세요 반갑습니다", "안녕하세여 반갑습니다") - 100 / 11) < 1e-9 and METRICS["CER"]["needs_ref"] and not METRICS["MOS"]["needs_ref"],
      "CER = 편집 거리 / 정답 글자 수, 참고 대본이 필요한 지표와 아닌 지표를 구분")

metrics.typescript:
// D20 · Part 1 · TTS 평가 지표 지도: 무엇을 재고 싶은가 → 어떤 지표 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d20_metrics.ts
//   MOS · CER · UTMOS · TTFA · RTF · LUFS · 화자 유사도가 각각 무엇을 재는지 표로 두고, 질문에서 지표를 고르는 함수와 CER 계산 예
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function editDistance(a: string[], b: string[]): number {
  // 레벤슈타인 편집 거리 (글자 · 낱말 열 모두 가능)
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] !== b[j - 1] ? 1 : 0)));
    }
    prev = cur;
  }
  return prev[b.length];
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율(%) = 편집 거리 / 정답 글자 수 x 100
  const r = [...ref];
  return (100 * editDistance(r, [...hyp])) / Math.max(r.length, 1);
}

type Metric = { measures: string; needsRef: boolean; cost: string };
const METRICS: Record<string, Metric> = {
  MOS: { measures: "사람이 듣기에 자연스러운가", needsRef: false, cost: "사람 평가자 필요 (비쌈)" },
  UTMOS: { measures: "자연스러움을 신경망이 예측", needsRef: false, cost: "자동 (싸지만 한국어 절대값 주의)" },
  CER: { measures: "말한 내용이 정확한가 (ASR로 되받아쓰기)", needsRef: true, cost: "자동 (ASR 필요)" },
  TTFA: { measures: "첫 소리까지 기다린 시간", needsRef: false, cost: "시계만 있으면 됨" },
  RTF: { measures: "합성 시간 / 소리 길이 (1 미만이면 실시간)", needsRef: false, cost: "시계만 있으면 됨" },
  LUFS: { measures: "방송 규격 음량", needsRef: false, cost: "신호만 있으면 됨" },
  "화자 유사도": { measures: "참고 목소리와 닮았는가", needsRef: true, cost: "자동 (화자 모델 필요)" },
};
const QUESTIONS: Record<string, string> = {
  "사람이 듣기에 자연스러운가?": "MOS", "읽어야 할 내용을 정확히 말하나?": "CER", "버튼을 누르고 얼마 만에 소리가 나나?": "TTFA",
  "방송 음량 규격에 맞나?": "LUFS", "복제한 목소리가 본인과 비슷한가?": "화자 유사도", "서버 한 대로 몇 명까지 동시에 합성할까?": "RTF",
};

const KEYWORDS: Record<string, string[]> = { MOS: ["자연스러", "듣기"], UTMOS: ["예측"], CER: ["정확", "내용"], TTFA: ["얼마 만에", "기다"],
  RTF: ["동시에", "실시간", "서버"], LUFS: ["음량", "방송"], "화자 유사도": ["본인", "비슷", "닮"] };

function pickMetric(question: string): string {
  // 질문에 든 핵심 낱말이 가장 많이 겹치는 지표를 고른다
  const score = (m: string): number => KEYWORDS[m].filter((k) => question.includes(k)).length;
  return Object.keys(METRICS).reduce((best, m) => (score(m) > score(best) ? m : best));
}

for (const [q, expected] of Object.entries(QUESTIONS)) console.log(`${q.padEnd(30)} -> ${expected}`);
const okPick = Object.entries(QUESTIONS).filter(([, m]) => m !== "UTMOS").every(([q, m]) => pickMetric(q) === m);
const sample = cer("안녕하세요 반갑습니다", "안녕하세여 반갑습니다");
console.log("CER 예:", sample.toFixed(1), "% (글자 1개 틀림 / 정답 11글자)");
check(okPick && Math.abs(sample - 100 / 11) < 1e-9 && METRICS["CER"].needsRef && !METRICS["MOS"].needsRef,
  "CER = 편집 거리 / 정답 글자 수, 참고 대본이 필요한 지표와 아닌 지표를 구분");

mos.typescript:
// D20 · Part 2 · 반 전체 MOS와 95% 신뢰구간 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d20_mos.ts
//   평가자 15명의 1~5점으로 시스템별 평균(MOS)과 t 분포 신뢰구간을 구하고, 구간이 겹치는지로 '정말 차이가 나는가'를 판단
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const T975 = [0, 12.706, 4.303, 3.182, 2.776, 2.571, 2.447, 2.365, 2.306, 2.262, 2.228, 2.201, 2.179, 2.160, 2.145, 2.131, 2.120, 2.110, 2.101, 2.093, 2.086, 2.080, 2.074, 2.069, 2.064, 2.060, 2.056, 2.052, 2.048, 2.045, 2.042]; // t 분포 0.975 값 표 (df 1~30, 그 위는 정규분포 1.96)

function mosCi(scores: number[]): { mean: number; half: number; n: number } {
  // 평균 점수(MOS)와 95% 신뢰구간 반폭 = t(0.975, n-1) x 표준편차 / sqrt(n)
  const n = scores.length;
  const mean = scores.reduce((a, b) => a + b, 0) / n;
  const sd = Math.sqrt(scores.reduce((a, b) => a + (b - mean) ** 2, 0) / (n - 1));
  const t = n - 1 <= 30 ? T975[n - 1] : 1.96;
  return { mean, half: (t * sd) / Math.sqrt(n), n };
}

function virtualClass(nRaters = 15, seed = 7): Record<string, number[]> {
  // 가상 반: 평가자 n명이 시스템마다 1~5점 (평가자마다 후한 정도가 다름)
  const r = rng(seed);
  const out: Record<string, number[]> = { A: [], B: [], C: [] };
  for (let i = 0; i < nRaters; i++) {
    const bias = 0.4 * gauss(r);
    for (const [s, mu] of Object.entries({ A: 4.3, B: 3.6, C: 2.9 })) out[s].push(Math.min(5, Math.max(1, Math.round(mu + bias + 0.6 * gauss(r)))));
  }
  return out;
}

const CLASS = virtualClass();
const res: Record<string, ReturnType<typeof mosCi>> = {};
for (const [s, v] of Object.entries(CLASS)) {
  res[s] = mosCi(v);
  console.log(`시스템 ${s}: MOS ${res[s].mean.toFixed(2)} ± ${res[s].half.toFixed(2)} (구간 ${(res[s].mean - res[s].half).toFixed(2)} ~ ${(res[s].mean + res[s].half).toFixed(2)}, 평가자 ${res[s].n}명)`);
}
const small = mosCi([4, 5, 3, 4, 4, 5, 3, 4]);
const overlap = (a: string, b: string): boolean =>
  res[a].mean - res[a].half < res[b].mean + res[b].half && res[b].mean - res[b].half < res[a].mean + res[a].half;
console.log("A와 B 구간이 겹침:", overlap("A", "B"), "· A와 C 구간이 겹침:", overlap("A", "C"));
const sd = Math.sqrt([4, 5, 3, 4, 4, 5, 3, 4].reduce((a, b) => a + (b - 4) ** 2, 0) / 7); // 평균 4
check(small.n === 8 && Math.abs(small.half - (2.365 * sd) / Math.sqrt(8)) < 1e-9
  && res["A"].mean > res["C"].mean && !overlap("A", "C"), "반폭의 분모는 sqrt(n), A와 C는 구간이 겹치지 않아야 해요");

utmos.typescript:
// D20 · Part 3 · 자동 지표 vs 사람: UTMOS · CER와 내 점수의 상관 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d20_utmos.ts
//   세 시스템 x 문장 4개(12개)에서 자동 점수(UTMOS 흉내)와 받아쓰기 오류율(CER)이 사람 점수와 얼마나 맞는지 상관계수로 본다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const SR = 24000;
const HANGUL = /[가-힣]/g;

function generate(text: string, exaggeration = 0.5, cfgWeight = 0.5, seed = 0, ref: { f0: number; depth: number } | null = null): Float32Array {
  // Chatterbox 흉내: 손잡이 -> 말 빠르기 · 음높이 폭 · 세기 변화 (신경망 대신 규칙 · 사인파)
  const r = rng(seed);
  const nSyl = Math.max((text.match(HANGUL) ?? []).length, 1);
  const rate = 3.5 + 2.5 * cfgWeight; // 음절/초: cfg_weight가 낮을수록 천천히 또박또박
  const sec = nSyl / rate + 0.4;
  const base = ref ? ref.f0 : 200; // 참고 음성이 있으면 그 목소리 높이 · 표현 폭을 따라간다
  const depth = ref ? ref.depth : 1;
  const phi = r() * 2 * Math.PI;
  const q = text.trimEnd().endsWith("?");
  const ex = text.trimEnd().endsWith("!");
  const y = new Float32Array(Math.floor(sec * SR));
  let phase = 0;
  for (let i = 0; i < y.length; i++) {
    const t = i / SR;
    let st = (((2 + 10 * exaggeration) * depth) / 2) * Math.sin(2 * Math.PI * (rate / 2) * t + phi); // 반음 단위 억양
    if (q) st += 4 * Math.min(1, Math.max(0, (t - (sec - 0.8)) / 0.6)); // 물음표: 끝이 올라감
    if (ex) st += 2; // 느낌표: 전체가 높아짐
    phase += (2 * Math.PI * base * 2 ** (st / 12)) / SR;
    const amp = 0.3 * (1 + 0.6 * exaggeration * Math.sin(2 * Math.PI * rate * t)) * (t < sec - 0.2 ? 1 : 0); // 끝 0.2초는 쉼
    y[i] = amp * Math.sin(phase);
  }
  return y;
}

function frameF0(y: Float32Array, sr = SR, frameSec = 0.05): { f0: number[]; hop: number } {
  // 50 ms 창마다 0 교차 시각으로 음높이(Hz)를 잰다. 소리 없는 창은 NaN
  const n = Math.floor(frameSec * sr);
  const hop = Math.floor(n / 2);
  const f0: number[] = [];
  for (let a = 0; a < y.length - n; a += hop) {
    const ts: number[] = [];
    let peak = 0;
    for (let i = 0; i < n; i++) {
      peak = Math.max(peak, Math.abs(y[a + i]));
      if (i > 0 && y[a + i - 1] < 0 && y[a + i] >= 0) ts.push(i - 1 + -y[a + i - 1] / (y[a + i] - y[a + i - 1])); // 샘플 사이를 직선으로 보간
    }
    f0.push(peak < 0.02 || ts.length < 3 ? NaN : ((ts.length - 1) / (ts[ts.length - 1] - ts[0])) * sr);
  }
  return { f0, hop };
}

const median = (x: number[]): number => { const s = [...x].sort((a, b) => a - b); return s[Math.floor((s.length - 1) / 2)] / 2 + s[Math.ceil((s.length - 1) / 2)] / 2; };
const percentile = (x: number[], p: number): number => {
  const s = [...x].sort((a, b) => a - b);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
};

function prosody(y: Float32Array, sr = SR, text: string | null = null) {
  // 운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초
  const { f0, hop } = frameF0(y, sr);
  const v = f0.filter((x) => !Number.isNaN(x));
  const med = median(v);
  const st = v.map((x) => 12 * Math.log2(x / med)); // 중앙값 대비 반음
  const db: number[] = [];
  for (let a = 0; a < y.length - hop * 2; a += hop) {
    let s = 0;
    for (let i = 0; i < hop * 2; i++) s += y[a + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / (hop * 2)) + 1e-6));
  }
  const top = Math.max(...db);
  const loud = db.filter((d) => d > top - 35);
  const m = loud.reduce((a, b) => a + b, 0) / loud.length;
  const speechSec = Math.max((loud.length * hop) / sr, 1e-3);
  return {
    pitchHz: med,
    rangeSt: percentile(st, 90) - percentile(st, 10),
    energyDb: Math.sqrt(loud.reduce((a, b) => a + (b - m) ** 2, 0) / loud.length),
    silence: 1 - speechSec / (y.length / sr),
    sylPerSec: text ? (text.match(HANGUL) ?? []).length / speechSec : NaN,
  };
}

function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

function editDistance(a: string[], b: string[]): number {
  // 레벤슈타인 편집 거리 (글자 · 낱말 열 모두 가능)
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] !== b[j - 1] ? 1 : 0)));
    }
    prev = cur;
  }
  return prev[b.length];
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율(%) = 편집 거리 / 정답 글자 수 x 100
  const r = [...ref];
  return (100 * editDistance(r, [...hyp])) / Math.max(r.length, 1);
}

function addNoise(y: Float32Array, snrDb: number, seed = 0): Float32Array {
  // 신호 대 잡음비가 snr_db가 되도록 흰 잡음을 더한다
  const r = rng(seed);
  const n = Float64Array.from({ length: y.length }, () => gauss(r));
  const pSig = y.reduce((a, v) => a + v * v, 0) / y.length;
  const pNoise = n.reduce((a, v) => a + v * v, 0) / n.length;
  const g = Math.sqrt(pSig / (pNoise * 10 ** (snrDb / 10)));
  return Float32Array.from(y, (v, i) => v + n[i] * g);
}

const SYSTEM_SNR: Record<string, number> = { A: 40, B: 25, C: 10 }; // 시스템마다 섞인 잡음 수준(dB): 클수록 깨끗
const SENTS = ["오늘은 사 주차 마지막 날입니다", "음성 합성의 원리부터 배웠습니다", "직접 만든 소리를 평가합니다", "끝까지 함께해 주셔서 고맙습니다"];

const makeSample = (system: string, k: number): Float32Array => addNoise(generate(SENTS[k], 0.4, 0.5, 20 + k), SYSTEM_SNR[system], k);

function snrEstimate(y: Float32Array): number {
  // 끝 쉼 구간의 잡음 전력 대비 말하는 구간 전력 (dB)
  const q = Math.floor(0.1 * SR);
  const t = Math.floor(0.2 * SR);
  const quiet = y.slice(y.length - q).reduce((a, v) => a + v * v, 0) / q;
  const loud = y.slice(0, y.length - t).reduce((a, v) => a + v * v, 0) / (y.length - t);
  return 10 * Math.log10(loud / quiet);
}

// UTMOS 흉내: 잡음이 적을수록 높은 1~5 점수 (진짜 UTMOS는 학습한 신경망)
const autoMos = (y: Float32Array): number => 1 + 4 * Math.min(1, Math.max(0, (snrEstimate(y) - 5) / 35));

function corrupt(text: string, p: number, seed: number): string {
  // 받아쓰기 대신: 글자를 확률 p로 틀리게 (잡음이 많을수록 p가 큼)
  const r = rng(seed);
  return [...text].map((c) => (r() < p ? "ㅇ" : c)).join("");
}

function pearson(a: number[], b: number[]): number {
  const ma = a.reduce((x, y) => x + y, 0) / a.length;
  const mb = b.reduce((x, y) => x + y, 0) / b.length;
  let sab = 0;
  let saa = 0;
  let sbb = 0;
  a.forEach((v, i) => { sab += (v - ma) * (b[i] - mb); saa += (v - ma) ** 2; sbb += (b[i] - mb) ** 2; });
  return sab / Math.sqrt(saa * sbb);
}

const r = rng(3);
const rows: { system: string; utmos: number; cer: number; my: number }[] = [];
for (const [sysname, mu] of Object.entries({ A: 4.5, B: 3.4, C: 2.0 })) {
  for (let k = 0; k < SENTS.length; k++) {
    const y = makeSample(sysname, k);
    const snr = snrEstimate(y);
    const heard = corrupt(SENTS[k], Math.min(0.5, Math.max(0, (32 - snr) / 50)), k); // 받아쓰기 대신 잡음에 따라 틀리게
    rows.push({ system: sysname, utmos: autoMos(y), cer: cer(SENTS[k], heard) / 100, my: Math.min(5, Math.max(1, Math.round(mu + 0.3 * gauss(r)))) }); // 가상의 내 점수
  }
}
const avg = (x: number[]): number => x.reduce((a, b) => a + b, 0) / x.length;
for (const s of ["A", "B", "C"]) {
  const g = rows.filter((x) => x.system === s);
  console.log(`${s}: UTMOS ${avg(g.map((x) => x.utmos)).toFixed(2)} · CER ${avg(g.map((x) => x.cer)).toFixed(2)} · 내 점수 ${avg(g.map((x) => x.my)).toFixed(2)}`);
}
const rU = pearson(rows.map((x) => x.my), rows.map((x) => x.utmos));
const rC = pearson(rows.map((x) => x.my), rows.map((x) => x.cer));
console.log(`내 점수 vs UTMOS 상관 ${rU.toFixed(2)} · 내 점수 vs CER 상관 ${rC.toFixed(2)} (CER은 낮을수록 좋으므로 음수가 정상)`);
check(rows.length === 12 && rU > 0.8 && rC < -0.6, "UTMOS는 양의 상관, CER은 음의 상관이어야 해요");

