  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
};

function prosody(y: Float32Array, sr = SR, text: string | null = null) {
  // 운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초
  const { f0, hop } = frameF0(y, sr);
  const v = f0.filter((x) => !Number.isNaN(x));
  const med = median(v);
  const st = v.map((x) => 12 * Math.log2(x / med)); // 중앙값 대비 반음
  const db: number[] = [];
  for (let a = 0; a < y.length - hop * 2; a += hop) {
    let s = 0;
    for (let i = 0; i < hop * 2; i++) s += y[a + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / (hop * 2)) + 1e-6));
  }
  const top = Math.max(...db);
  const loud = db.filter((d) => d > top - 35);
  const m = loud.reduce((a, b) => a + b, 0) / loud.length;
  const speechSec = Math.max((loud.length * hop) / sr, 1e-3);
  return {
    pitchHz: med,
    rangeSt: percentile(st, 90) - percentile(st, 10),
    energyDb: Math.sqrt(loud.reduce((a, b) => a + (b - m) ** 2, 0) / loud.length),
    silence: 1 - speechSec / (y.length / sr),
    sylPerSec: text ? (text.match(HANGUL) ?? []).length / speechSec : NaN,
  };
}

function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

const PARA = "오늘은 사 주차 마지막 날입니다. 우리는 음성 합성의 원리부터 감정 조절과 목소리 복제까지 배웠습니다. 이제 직접 만든 소리를 평가하고, 오디오북 생성기를 완성합니다. 끝까지 함께해 주셔서 고맙습니다.";
const SENTS = PARA.split(/(?<=[.!?])\s+/).filter((s) => s);

function timeline(chunks: string[], rtf: number): { ttfa: number; stalls: number } {
  // 조각마다 준비 시각 · 길이를 구하고, TTFA와 끊김 수를 낸다 (합성 시간 = RTF x 소리 길이)
  const lens = chunks.map((c, k) => generate(c, 0.5, 0.5, k).length / SR);
  let t = 0;
  const ready = lens.map((l) => (t += rtf * l));
  const ttfa = ready[0]; // 첫 조각이 준비된 시각
  let played = 0;
  let stalls = 0;
  lens.forEach((l, i) => { // 앞 조각이 끝나는 시각에 다음 조각 재생
    if (ready[i] > ttfa + played + 1e-9) stalls++;
    played += l;
  });
  return { ttfa, stalls };
}

const w = timeline([PARA], 0.3);
const s = timeline(SENTS, 0.3);
const slow = timeline(SENTS, 1.4);
console.log(`RTF 0.3: 통째로 TTFA ${w.ttfa.toFixed(2)}초 · 문장마다 TTFA ${s.ttfa.toFixed(2)}초 · 끊김 ${s.stalls}번`);
console.log(`RTF 1.4(합성이 재생보다 느림): 끊김 ${slow.stalls}번`);
check(s.ttfa < w.ttfa && s.stalls === 0 && slow.stalls >= 1 && SENTS.length === 4, "문장마다 합성하면 TTFA가 줄고, RTF > 1이면 끊겨요");

gen.python:
# D20 · Part 5 · 미니 프로젝트: 오디오북 · 안내방송 생성기 파이프라인 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6 soundfile==0.14.0
# 실행: python d20_gen.py   (인터넷 · GPU · 마이크 불필요 · UTMOS · Whisper · Chatterbox 대신 장난감 모델)
#   원고 쪼개기 → 문장마다 합성 + 품질 게이트(CER) → 쉼 · 딩동댕 → 워터마크 → 마스터링 → SRT · WAV 저장 (장난감 목소리)
import re
import numpy as np
import soundfile as sf

def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")

SR = 24000
HANGUL = re.compile(r"[가-힣]")


def generate(text: str, exaggeration: float = 0.5, cfg_weight: float = 0.5, seed: int = 0, ref: dict = None) -> np.ndarray:
    """Chatterbox 흉내: 손잡이 -> 말 빠르기 · 음높이 폭 · 세기 변화 (신경망 대신 규칙 · 사인파)"""
    rng = np.random.default_rng(seed)
    n_syl = max(len(HANGUL.findall(text)), 1)
    rate = 3.5 + 2.5 * cfg_weight                              # 음절/초: cfg_weight가 낮을수록 천천히 또박또박
    sec = n_syl / rate + 0.4
    t = np.arange(int(sec * SR)) / SR
    base = 200.0 if ref is None else ref["f0"]                  # 참고 음성이 있으면 그 목소리 높이 · 표현 폭을 따라간다
    depth = 1.0 if ref is None else ref["depth"]
    st = ((2 + 10 * exaggeration) * depth / 2) * np.sin(2 * np.pi * (rate / 2) * t + rng.uniform(0, 2 * np.pi))   # 반음 단위 억양
    if text.rstrip().endswith("?"):
        st += 4 * np.clip((t - (sec - 0.8)) / 0.6, 0, 1)         # 물음표: 끝이 올라감
    if text.rstrip().endswith("!"):
        st += 2                                                  # 느낌표: 전체가 높아짐
    f0 = base * 2 ** (st / 12)
    amp = 0.3 * (1 + 0.6 * exaggeration * np.sin(2 * np.pi * rate * t)) * (t < sec - 0.2)   # 끝 0.2초는 쉼
    return (amp * np.sin(2 * np.pi * np.cumsum(f0) / SR)).astype(np.float32)


def frame_f0(y: np.ndarray, sr: int = SR, frame_sec: float = 0.05):
    """50 ms 창마다 0 교차 시각으로 음높이(Hz)를 잰다. 소리 없는 창은 nan"""
    n = int(frame_sec * sr)
    hop = n // 2
    out = []
    for a in range(0, len(y) - n, hop):
        w = y[a:a + n].astype(np.float64)
        idx = np.where((w[:-1] < 0) & (w[1:] >= 0))[0]
        if np.abs(w).max() < 0.02 or len(idx) < 3:
            out.append(np.nan)
            continue
        ts = idx + (-w[idx]) / (w[idx + 1] - w[idx])               # 0을 지나는 시각 (샘플 사이를 직선으로 보간)
        out.append((len(ts) - 1) / (ts[-1] - ts[0]) * sr)
    return np.array(out), hop


def prosody(y: np.ndarray, sr: int = SR, text: str = None) -> dict:
    """운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초"""
    f0, hop = frame_f0(y, sr)
    v = f0[~np.isnan(f0)]
    st = 12 * np.log2(v / np.median(v))                            # 중앙값 대비 반음
    rms = np.array([np.sqrt(np.mean(y[a:a + hop * 2] ** 2)) for a in range(0, len(y) - hop * 2, hop)])
    db = 20 * np.log10(rms + 1e-6)
    loud = db[db > db.max() - 35]
    speech_sec = max(float((db > db.max() - 35).sum()) * hop / sr, 1e-3)
    out = dict(pitch_hz=float(np.median(v)), range_st=float(np.percentile(st, 90) - np.percentile(st, 10)),
               energy_db=float(loud.std()), silence=float(1 - speech_sec / (len(y) / sr)))
    out["syl_per_sec"] = len(HANGUL.findall(text)) / speech_sec if text else float("nan")
    return out


def tail_semitone(y: np.ndarray, sr: int = SR) -> float:
    """끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)"""
    f0, hop = frame_f0(y, sr)
    t = np.arange(len(f0)) * hop / sr
    ok = ~np.isnan(f0)
    end = t[ok][-1]
    return float(np.mean(12 * np.log2(f0[ok & (t > end - 0.6)] / np.median(f0[ok]))))

def edit_distance(a, b) -> int:
    """레벤슈타인 편집 거리 (글자 · 낱말 열 모두 가능)"""
    prev = list(range(len(b) + 1))
    for i, x in enumerate(a, 1):
        cur = [i]
        for j, y in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (x != y)))
        prev = cur
    return prev[-1]


def cer(ref: str, hyp: str) -> float:
    """글자 오류율(%) = 편집 거리 / 정답 글자 수 x 100"""
    return 100 * edit_distance(ref, hyp) / max(len(ref), 1)

WM_REL, HOLD = 0.1, 4          # 워터마크 세기 = 소리 크기(rms)의 10% · 같은 값을 4샘플씩 유지(낮은 소리 쪽에 모여 전화 음질에도 남음)


def wm_key(n: int, secret: int = 1234) -> np.ndarray:
    """비밀 값에서 만든 +1/-1 열 (xorshift32). 같은 비밀이면 같은 열 -> 검출기가 알아본다"""
    x, bits = secret & 0xFFFFFFFF, np.empty(-(-n // HOLD))
    for i in range(len(bits)):
        x ^= (x << 13) & 0xFFFFFFFF
        x ^= x >> 17
        x ^= (x << 5) & 0xFFFFFFFF
        bits[i] = 1.0 if x & 1 else -1.0
    return np.repeat(bits, HOLD)[:n]


def rms(y: np.ndarray) -> float:
    return float(np.sqrt(np.mean(np.asarray(y, dtype=np.float64) ** 2)) + 1e-12)


def apply_watermark(y: np.ndarray) -> np.ndarray:
    """소리에 비밀 열을 작게 더한다 (Perth 워터마커의 아이디어만 흉내)"""
    return (y + WM_REL * rms(y) * wm_key(len(y))).astype(np.float32)


def get_watermark(y: np.ndarray) -> float:
    """비밀 열과 얼마나 닮았나 0~1 (소리 크기와 무관). 0.5 이상이면 '워터마크 있음'. 시작 위치가 어긋나면 못 찾는다"""
    return float(np.clip(np.mean(y * wm_key(len(y))) / (WM_REL * rms(y)), 0, 1))

def srt_time(sec: float) -> str:
    """초 -> SRT 자막 시각 00:00:00,000"""
    total_ms = int(round(sec * 1000))
    h, rem = divmod(total_ms, 3_600_000)
    m, rem = divmod(rem, 60_000)
    s, ms = divmod(rem, 1000)
    return f"{h:02d}:{m:02d}:{s:02d},{ms:03d}"

def lufs(y: np.ndarray) -> float:
    """음량(LUFS) 단순 측정: -0.691 + 10 x log10(평균 제곱). 진짜 LUFS의 K 가중 필터 · 게이팅은 생략"""
    return float(-0.691 + 10 * np.log10(np.mean(y.astype(np.float64) ** 2) + 1e-12))


def peak_db(y: np.ndarray) -> float:
    return float(20 * np.log10(np.max(np.abs(y)) + 1e-9))


def silence(sec: float) -> np.ndarray:
    return np.zeros(int(sec * SR), np.float32)


def master(y: np.ndarray, target_lufs: float, peak_max_db: float = -1.0):
    """음량을 목표 LUFS에 맞추고, 피크가 상한을 넘으면 전체를 조금 줄인다 (간단한 리미터)"""
    y = y * 10 ** ((target_lufs - lufs(y)) / 20)
    if peak_db(y) > peak_max_db:
        y = y * 10 ** ((peak_max_db - peak_db(y)) / 20)
    y = y.astype(np.float32)
    return y, lufs(y), peak_db(y)

CER_GATE, N_TRY = 0.15, 3
DISCLOSURE = "이 음성은 인공지능으로 만든 음성입니다."
MODES = {"audiobook": dict(exaggeration=0.35, cfg_weight=0.5, pause_sent=0.35, pause_para=0.9, target_lufs=-18.0, chime=False, repeat=1),
         "announce": dict(exaggeration=0.5, cfg_weight=0.5, pause_sent=0.5, pause_para=0.8, target_lufs=-16.0, chime=True, repeat=2)}


def chime(up: bool = True) -> np.ndarray:
    """안내방송 '딩동댕' (C5 · E5 · G5, 끝날 때는 거꾸로)"""
    freqs = [523.25, 659.25, 783.99] if up else [783.99, 659.25, 523.25]
    out = np.zeros(int(2.0 * SR), np.float32)
    t = np.arange(int(1.3 * SR)) / SR
    for k, f in enumerate(freqs):
        tone = (np.sin(2 * np.pi * f * t) + 0.3 * np.sin(2 * np.pi * 2 * f * t)) * np.exp(-3.2 * t)
        a = int(k * 0.42 * SR)
        out[a:a + len(t)] += tone[: len(out) - a]
    return (0.15 * out / np.abs(out).max()).astype(np.float32)


def split_script(script: str) -> list:
    paras = [p.strip() for p in re.split(r"\n\s*\n", script.strip()) if p.strip()]
    return [[s for s in re.split(r"(?<=[.!?])\s+", p) if s] for p in paras]


def synth_best(text: str, cfg: dict) -> dict:
    """품질 게이트: CER이 기준 이하가 될 때까지 씨앗을 바꿔 최대 N_TRY번 만들고, 가장 낮은 CER을 고른다"""
    cands = []
    for k in range(N_TRY):
        y = generate(text, cfg["exaggeration"], cfg["cfg_weight"], seed=100 + k)
        heard = corrupt(text, 0.12, seed=100 + k)                 # 받아쓰기 대신: 시도마다 다른 오류 (씨앗이 다르면 결과도 다름)
        cands.append(dict(y=y, cer=cer(text, heard) / 100))
        if cands[-1]["cer"] <= CER_GATE:
            break
    best = min(cands, key=lambda c: c["cer"])
    return dict(best, tries=len(cands), all_cer=[round(c["cer"], 3) for c in cands])


def make_program(script: str, mode: str, name: str):
    cfg, parts, segs, rows, cache, cursor = MODES[mode], [], [], [], {}, [0]

    def add(y, text=None):
        if text:
            segs.append((cursor[0] / SR, (cursor[0] + len(y)) / SR, text))
        parts.append(y)
        cursor[0] += len(y)

    add(generate(DISCLOSURE, 0.3, 0.5, seed=0), DISCLOSURE)        # D19 고지로 시작
    add(silence(0.6))
    for rep in range(cfg["repeat"]):
        if cfg["chime"]:
            add(chime(True))
            add(silence(0.3))
        for pi, sents in enumerate(split_script(script)):
            for s in sents:
                if s not in cache:
                    cache[s] = synth_best(s, cfg)
                    rows.append(dict(para=pi + 1, text=s, cer=cache[s]["cer"], cands=cache[s]["all_cer"], tries=cache[s]["tries"],
                                     gate=cache[s]["cer"] <= CER_GATE))
                add(cache[s]["y"], s)
                add(silence(cfg["pause_sent"]))
            add(silence(cfg["pause_para"]))
        if cfg["chime"]:
            add(chime(False))
        if rep < cfg["repeat"] - 1:
            add(silence(1.0))
    y = apply_watermark(np.concatenate(parts))                    # 워터마크 -> 마스터링 (볼륨 변화에 강함)
    y, lu, pk = master(y, cfg["target_lufs"])
    with open(f"{name}.srt", "w", encoding="utf-8") as f:
        for i, (a, b, t) in enumerate(segs, 1):
            f.write(f"{i}\n{srt_time(a)} --> {srt_time(b)}\n{t}\n\n")
    sf.write(f"{name}.wav", y, SR)                                 # mp3 변환은 ffmpeg가 있을 때만 (여기선 생략)
    report = dict(name=name, mode=mode, sec=round(len(y) / SR, 1), lufs=round(lu, 1), peak=round(pk, 1), wm=round(get_watermark(y), 2),
                  gate_rate=round(float(np.mean([r["gate"] for r in rows])), 2), mean_cer=round(float(np.mean([r["cer"] for r in rows])), 3), subs=len(segs))
    return y, rows, report

def corrupt(text: str, p: float, seed: int) -> str:
    """받아쓰기 대신: 글자를 확률 p로 틀리게"""
    rng = np.random.default_rng(seed)
    return "".join("ㅇ" if rng.random() < p else c for c in text)


SCRIPT = "옛날 옛적, 깊은 산속 작은 마을에 마음씨 착한 나무꾼이 살았습니다. 나무꾼은 매일 아침 일찍 산에 올랐습니다.\n\n어느 날, 연못가에서 나무를 하던 나무꾼은 그만 도끼를 물에 빠뜨리고 말았습니다. 나무꾼은 한숨을 쉬며 주저앉았습니다."
book, rows, report = make_program(SCRIPT, "audiobook", "audiobook")
for r in rows:
    print(f"CER {r['cer']:.3f} 후보 {r['cands']} {'통과' if r['gate'] else '미달'} · {r['text'][:20]}")
print(report)
print(open("audiobook.srt", encoding="utf-8").read()[:120])
check(all(round(r["cer"], 3) == min(r["cands"]) for r in rows) and report["subs"] == len(rows) + 1
      and abs(report["lufs"] + 18) < 0.5 and report["peak"] <= -1.0 + 1e-3 and report["wm"] >= 0.5
      and sf.info("audiobook.wav").samplerate == SR, "게이트는 후보 중 가장 낮은 CER을 고르고, 자막은 고지 + 문장 수만큼이어야 해요")

gen.typescript:
// D20 · Part 5 · 미니 프로젝트: 오디오북 · 안내방송 생성기 파이프라인 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d20_gen.ts
//   원고 쪼개기 → 문장마다 합성 + 품질 게이트(CER) → 쉼 · 딩동댕 → 워터마크 → 마스터링 → SRT · WAV 저장 (장난감 목소리)
import { writeFileSync } from "node:fs";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const SR = 24000;
const HANGUL = /[가-힣]/g;

function generate(text: string, exaggeration = 0.5, cfgWeight = 0.5, seed = 0, ref: { f0: number; depth: number } | null = null): Float32Array {
  // Chatterbox 흉내: 손잡이 -> 말 빠르기 · 음높이 폭 · 세기 변화 (신경망 대신 규칙 · 사인파)
  const r = rng(seed);
  const nSyl = Math.max((text.match(HANGUL) ?? []).length, 1);
  const rate = 3.5 + 2.5 * cfgWeight; // 음절/초: cfg_weight가 낮을수록 천천히 또박또박
  const sec = nSyl / rate + 0.4;
  const base = ref ? ref.f0 : 200; // 참고 음성이 있으면 그 목소리 높이 · 표현 폭을 따라간다
  const depth = ref ? ref.depth : 1;
  const phi = r() * 2 * Math.PI;
  const q = text.trimEnd().endsWith("?");
  const ex = text.trimEnd().endsWith("!");
  const y = new Float32Array(Math.floor(sec * SR));
  let phase = 0;
  for (let i = 0; i < y.length; i++) {
    const t = i / SR;
    let st = (((2 + 10 * exaggeration) * depth) / 2) * Math.sin(2 * Math.PI * (rate / 2) * t + phi); // 반음 단위 억양
    if (q) st += 4 * Math.min(1, Math.max(0, (t - (sec - 0.8)) / 0.6)); // 물음표: 끝이 올라감
    if (ex) st += 2; // 느낌표: 전체가 높아짐
    phase += (2 * Math.PI * base * 2 ** (st / 12)) / SR;
    const amp = 0.3 * (1 + 0.6 * exaggeration * Math.sin(2 * Math.PI * rate * t)) * (t < sec - 0.2 ? 1 : 0); // 끝 0.2초는 쉼
    y[i] = amp * Math.sin(phase);
  }
  return y;
}

function frameF0(y: Float32Array, sr = SR, frameSec = 0.05): { f0: number[]; hop: number } {
  // 50 ms 창마다 0 교차 시각으로 음높이(Hz)를 잰다. 소리 없는 창은 NaN
  const n = Math.floor(frameSec * sr);
  const hop = Math.floor(n / 2);
  const f0: number[] = [];
  for (let a = 0; a < y.length - n; a += hop) {
    const ts: number[] = [];
    let peak = 0;
    for (let i = 0; i < n; i++) {
      peak = Math.max(peak, Math.abs(y[a + i]));
      if (i > 0 && y[a + i - 1] < 0 && y[a + i] >= 0) ts.push(i - 1 + -y[a + i - 1] / (y[a + i] - y[a + i - 1])); // 샘플 사이를 직선으로 보간
    }
    f0.push(peak < 0.02 || ts.length < 3 ? NaN : ((ts.length - 1) / (ts[ts.length - 1] - ts[0])) * sr);
  }
  return { f0, hop };
}

const median = (x: number[]): number => { const s = [...x].sort((a, b) => a - b); return s[Math.floor((s.length - 1) / 2)] / 2 + s[Math.ceil((s.length - 1) / 2)] / 2; };
const percentile = (x: number[], p: number): number => {
  const s = [...x].sort((a, b) => a - b);
  const k = ((s.length - 1) * p) / 100;
  const lo = Math.floor(k);
  return s[lo] + (s[Math.min(lo + 1, s.length - 1)] - s[lo]) * (k - lo);
};

function prosody(y: Float32Array, sr = SR, text: string | null = null) {
  // 운율을 숫자로: 음높이 · 음높이 폭(반음) · 세기 변화(dB) · 무음 비율 · 음절/초
  const { f0, hop } = frameF0(y, sr);
  const v = f0.filter((x) => !Number.isNaN(x));
  const med = median(v);
  const st = v.map((x) => 12 * Math.log2(x / med)); // 중앙값 대비 반음
  const db: number[] = [];
  for (let a = 0; a < y.length - hop * 2; a += hop) {
    let s = 0;
    for (let i = 0; i < hop * 2; i++) s += y[a + i] ** 2;
    db.push(20 * Math.log10(Math.sqrt(s / (hop * 2)) + 1e-6));
  }
  const top = Math.max(...db);
  const loud = db.filter((d) => d > top - 35);
  const m = loud.reduce((a, b) => a + b, 0) / loud.length;
  const speechSec = Math.max((loud.length * hop) / sr, 1e-3);
  return {
    pitchHz: med,
    rangeSt: percentile(st, 90) - percentile(st, 10),
    energyDb: Math.sqrt(loud.reduce((a, b) => a + (b - m) ** 2, 0) / loud.length),
    silence: 1 - speechSec / (y.length / sr),
    sylPerSec: text ? (text.match(HANGUL) ?? []).length / speechSec : NaN,
  };
}

function tailSemitone(y: Float32Array, sr = SR): number {
  // 끝 0.6초(쉼 제외)의 평균 음높이를 전체 중앙값 대비 반음으로 (물음표 판정용)
  const { f0, hop } = frameF0(y, sr);
  const t = f0.map((_, i) => (i * hop) / sr);
  const ok = f0.map((x) => !Number.isNaN(x));
  const med = median(f0.filter((_, i) => ok[i]));
  const end = Math.max(...t.filter((_, i) => ok[i]));
  const tail = f0.filter((_, i) => ok[i] && t[i] > end - 0.6).map((x) => 12 * Math.log2(x / med));
  return tail.reduce((a, b) => a + b, 0) / tail.length;
}

function editDistance(a: string[], b: string[]): number {
  // 레벤슈타인 편집 거리 (글자 · 낱말 열 모두 가능)
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] !== b[j - 1] ? 1 : 0)));
    }
    prev = cur;
  }
  return prev[b.length];
}

function cer(ref: string, hyp: string): number {
  // 글자 오류율(%) = 편집 거리 / 정답 글자 수 x 100
  const r = [...ref];
  return (100 * editDistance(r, [...hyp])) / Math.max(r.length, 1);
}

const WM_REL = 0.1; // 워터마크 세기 = 소리 크기(rms)의 10%
const HOLD = 4; // 같은 값을 4샘플씩 유지(낮은 소리 쪽에 모여 전화 음질에도 남음)

function wmKey(n: number, secret = 1234): Float64Array {
  // 비밀 값에서 만든 +1/-1 열 (xorshift32). 같은 비밀이면 같은 열 -> 검출기가 알아본다
  let x = secret >>> 0;
  const out = new Float64Array(n);
  for (let i = 0; i < n; i += HOLD) {
    x = (x ^ (x << 13)) >>> 0;
    x = (x ^ (x >>> 17)) >>> 0;
    x = (x ^ (x << 5)) >>> 0;
    for (let j = i; j < Math.min(i + HOLD, n); j++) out[j] = x & 1 ? 1 : -1;
  }
  return out;
}

function rms(y: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < y.length; i++) s += y[i] * y[i];
  return Math.sqrt(s / y.length) + 1e-12;
}

function applyWatermark(y: Float32Array): Float32Array {
  // 소리에 비밀 열을 작게 더한다 (Perth 워터마커의 아이디어만 흉내)
  const k = wmKey(y.length);
  const r = rms(y);
  return Float32Array.from(y, (v, i) => v + WM_REL * r * k[i]);
}

function getWatermark(y: Float32Array): number {
  // 비밀 열과 얼마나 닮았나 0~1 (소리 크기와 무관). 0.5 이상이면 '워터마크 있음'. 시작 위치가 어긋나면 못 찾는다
  const k = wmKey(y.length);
  let s = 0;
  for (let i = 0; i < y.length; i++) s += y[i] * k[i];
  return Math.min(1, Math.max(0, s / y.length / (WM_REL * rms(y))));
}

function srtTime(sec: number): string {
  // 초 -> SRT 자막 시각 00:00:00,000
  let rem = Math.round(sec * 1000);
  const h = Math.floor(rem / 3_600_000);
  rem -= h * 3_600_000;
  const m = Math.floor(rem / 60_000);
  rem -= m * 60_000;
  const s = Math.floor(rem / 1000);
  const p = (x: number, n: number) => String(x).padStart(n, "0");
  return `${p(h, 2)}:${p(m, 2)}:${p(s, 2)},${p(rem - s * 1000, 3)}`;
}

function lufs(y: Float32Array): number {
  // 음량(LUFS) 단순 측정: -0.691 + 10 x log10(평균 제곱). 진짜 LUFS의 K 가중 필터 · 게이팅은 생략
  return -0.691 + 10 * Math.log10(y.reduce((a, v) => a + v * v, 0) / y.length + 1e-12);
}

const peakDb = (y: Float32Array): number => 20 * Math.log10(y.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9);
const silence = (sec: number): Float32Array => new Float32Array(Math.floor(sec * SR));

function master(input: Float32Array, targetLufs: number, peakMaxDb = -1.0): { y: Float32Array; lufs: number; peak: number } {
  // 음량을 목표 LUFS에 맞추고, 피크가 상한을 넘으면 전체를 조금 줄인다 (간단한 리미터)
  let g = 10 ** ((targetLufs - lufs(input)) / 20);
  let y = Float32Array.from(input, (v) => v * g);
  if (peakDb(y) > peakMaxDb) {
    g = 10 ** ((peakMaxDb - peakDb(y)) / 20);
    y = y.map((v) => v * g);
  }
  return { y, lufs: lufs(y), peak: peakDb(y) };
}

const CER_GATE = 0.15;
const N_TRY = 3;
const DISCLOSURE = "이 음성은 인공지능으로 만든 음성입니다.";
type Cfg = { exaggeration: number; cfg_weight: number; pause_sent: number; pause_para: number; target_lufs: number; chime: boolean; repeat: number };
const MODES: Record<string, Cfg> = {
  audiobook: { exaggeration: 0.35, cfg_weight: 0.5, pause_sent: 0.35, pause_para: 0.9, target_lufs: -18.0, chime: false, repeat: 1 },
  announce: { exaggeration: 0.5, cfg_weight: 0.5, pause_sent: 0.5, pause_para: 0.8, target_lufs: -16.0, chime: true, repeat: 2 },
};

function chime(up = true): Float32Array {
  // 안내방송 '딩동댕' (C5 · E5 · G5, 끝날 때는 거꾸로)
  const freqs = up ? [523.25, 659.25, 783.99] : [783.99, 659.25, 523.25];
  const out = new Float32Array(Math.floor(2.0 * SR));
  const n = Math.floor(1.3 * SR);
  freqs.forEach((f, k) => {
    const a = Math.floor(k * 0.42 * SR);
    for (let i = 0; i < n && a + i < out.length; i++) {
      const t = i / SR;
      out[a + i] += (Math.sin(2 * Math.PI * f * t) + 0.3 * Math.sin(2 * Math.PI * 2 * f * t)) * Math.exp(-3.2 * t);
    }
  });
  const peak = out.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  return out.map((v) => (0.15 * v) / peak);
}

function splitScript(script: string): string[][] {
  const paras = script.trim().split(/\n\s*\n/).map((p) => p.trim()).filter((p) => p);
  return paras.map((p) => p.split(/(?<=[.!?])\s+/).filter((s) => s));
}

type Best = { y: Float32Array; cer: number; tries: number; allCer: number[] };

function synthBest(text: string, cfg: Cfg): Best {
  // 품질 게이트: CER이 기준 이하가 될 때까지 씨앗을 바꿔 최대 N_TRY번 만들고, 가장 낮은 CER을 고른다
  const cands: { y: Float32Array; cer: number }[] = [];
  for (let k = 0; k < N_TRY; k++) {
    const y = generate(text, cfg.exaggeration, cfg.cfg_weight, 100 + k);
    const heard = corrupt(text, 0.12, 100 + k); // 받아쓰기 대신: 시도마다 다른 오류 (씨앗이 다르면 결과도 다름)
    cands.push({ y, cer: cer(text, heard) / 100 });
    if (cands[cands.length - 1].cer <= CER_GATE) break;
  }
  const best = cands.reduce((a, b) => (b.cer < a.cer ? b : a));
  return { y: best.y, cer: best.cer, tries: cands.length, allCer: cands.map((c) => +c.cer.toFixed(3)) };
}

function wavBytes(y: Float32Array, sr: number): Buffer {
  // 16비트 PCM WAV 파일 바이트
  const b = Buffer.alloc(44 + y.length * 2);
  b.write("RIFF", 0); b.writeUInt32LE(36 + y.length * 2, 4); b.write("WAVEfmt ", 8);
  b.writeUInt32LE(16, 16); b.writeUInt16LE(1, 20); b.writeUInt16LE(1, 22); b.writeUInt32LE(sr, 24); b.writeUInt32LE(sr * 2, 28);
  b.writeUInt16LE(2, 32); b.writeUInt16LE(16, 34); b.write("data", 36); b.writeUInt32LE(y.length * 2, 40);
  y.forEach((v, i) => b.writeInt16LE(Math.round(Math.max(-1, Math.min(1, v)) * 32767), 44 + i * 2));
  return b;
}

function makeProgram(script: string, mode: string, name: string) {
  const cfg = MODES[mode];
  const parts: Float32Array[] = [];
  const segs: [number, number, string][] = [];
  const rows: { text: string; cer: number; allCer: number[]; gate: boolean }[] = [];
  const cache: Record<string, Best> = {};
  let cursor = 0;
  const add = (y: Float32Array, text?: string): void => {
    if (text) segs.push([cursor / SR, (cursor + y.length) / SR, text]);
    parts.push(y);
    cursor += y.length;
  };
  add(generate(DISCLOSURE, 0.3, 0.5, 0), DISCLOSURE); // D19 고지로 시작
  add(silence(0.6));
  for (let rep = 0; rep < cfg.repeat; rep++) {
    if (cfg.chime) { add(chime(true)); add(silence(0.3)); }
    for (const sents of splitScript(script)) {
      for (const s of sents) {
        if (!(s in cache)) {
          cache[s] = synthBest(s, cfg);
          rows.push({ text: s, cer: cache[s].cer, allCer: cache[s].allCer, gate: cache[s].cer <= CER_GATE });
        }
        add(cache[s].y, s);
        add(silence(cfg.pause_sent));
      }
      add(silence(cfg.pause_para));
    }
    if (cfg.chime) add(chime(false));
    if (rep < cfg.repeat - 1) add(silence(1.0));
  }
  const total = parts.reduce((a, p) => a + p.length, 0);
  const joined = new Float32Array(total);
  let off = 0;
  for (const p of parts) { joined.set(p, off); off += p.length; }
  const m = master(applyWatermark(joined), cfg.target_lufs); // 워터마크 -> 마스터링 (볼륨 변화에 강함)
  writeFileSync(`${name}.srt`, segs.map(([a, b, t], i) => `${i + 1}\n${srtTime(a)} --> ${srtTime(b)}\n${t}\n`).join("\n") + "\n", "utf-8");
  writeFileSync(`${name}.wav`, wavBytes(m.y, SR)); // mp3 변환은 ffmpeg가 있을 때만 (여기선 생략)
  const report = { name, mode, sec: +(m.y.length / SR).toFixed(1), lufs: +m.lufs.toFixed(1), peak: +m.peak.toFixed(1), wm: +getWatermark(m.y).toFixed(2), subs: segs.length };
  return { y: m.y, rows, report };
}

function corrupt(text: string, p: number, seed: number): string {
  // 받아쓰기 대신: 글자를 확률 p로 틀리게
  const r = rng(seed);
  return [...text].map((c) => (r() < p ? "ㅇ" : c)).join("");
}

const SCRIPT = "옛날 옛적, 깊은 산속 작은 마을에 마음씨 착한 나무꾼이 살았습니다. 나무꾼은 매일 아침 일찍 산에 올랐습니다.\n\n어느 날, 연못가에서 나무를 하던 나무꾼은 그만 도끼를 물에 빠뜨리고 말았습니다. 나무꾼은 한숨을 쉬며 주저앉았습니다.";
const { rows, report } = makeProgram(SCRIPT, "audiobook", "audiobook");
for (const r of rows) console.log(`CER ${r.cer.toFixed(3)} 후보 [${r.allCer}] ${r.gate ? "통과" : "미달"} · ${r.text.slice(0, 20)}`);
console.log(report);
check(rows.every((r) => +r.cer.toFixed(3) === Math.min(...r.allCer)) && report.subs === rows.length + 1
  && Math.abs(report.lufs + 18) < 0.5 && report.peak <= -1.0 + 1e-3 && report.wm >= 0.5, "게이트는 후보 중 가장 낮은 CER을 고르고, 자막은 고지 + 문장 수만큼이어야 해요");

loud.typescript:
// D20 · Part 5 · 편집 · 마스터링 도구: 쉼 · 음량(LUFS) · 피크 · 자막 시각 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d20_loud.ts
//   쉼 샘플 수, 목표 LUFS로 음량 맞추기, 피크 상한 −1 dBFS 리미터, 초 → SRT 시각 변환 (K 가중 없는 단순 LUFS)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rng(seed: number): () => number {
  // 시드를 고정하면 매번 같은 수열이 나오는 난수 (mulberry32)
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(r: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

const SR = 24000;

function lufs(y: Float32Array): number {
  // 음량(LUFS) 단순 측정: -0.691 + 10 x log10(평균 제곱). 진짜 LUFS의 K 가중 필터 · 게이팅은 생략
  return -0.691 + 10 * Math.log10(y.reduce((a, v) => a + v * v, 0) / y.length + 1e-12);
}

const peakDb = (y: Float32Array): number => 20 * Math.log10(y.reduce((m, v) => Math.max(m, Math.abs(v)), 0) + 1e-9);
const silence = (sec: number): Float32Array => new Float32Array(Math.floor(sec * SR));

function master(input: Float32Array, targetLufs: number, peakMaxDb = -1.0): { y: Float32Array; lufs: number; peak: number } {
  // 음량을 목표 LUFS에 맞추고, 피크가 상한을 넘으면 전체를 조금 줄인다 (간단한 리미터)
  let g = 10 ** ((targetLufs - lufs(input)) / 20);
  let y = Float32Array.from(input, (v) => v * g);
  if (peakDb(y) > peakMaxDb) {
    g = 10 ** ((peakMaxDb - peakDb(y)) / 20);
    y = y.map((v) => v * g);
  }
  return { y, lufs: lufs(y), peak: peakDb(y) };
}

function srtTime(sec: number): string {
  // 초 -> SRT 자막 시각 00:00:00,000
  let rem = Math.round(sec * 1000);
  const h = Math.floor(rem / 3_600_000);
  rem -= h * 3_600_000;
  const m = Math.floor(rem / 60_000);
  rem -= m * 60_000;
  const s = Math.floor(rem / 1000);
  const p = (x: number, n: number) => String(x).padStart(n, "0");
  return `${p(h, 2)}:${p(m, 2)}:${p(s, 2)},${p(rem - s * 1000, 3)}`;
}

const r = rng(0);
const test = Float32Array.from({ length: SR * 3 }, () => 0.05 * gauss(r)); // 합성 신호: 잡음 3초
const m = master(test, -18.0);
console.log(`쉼 0.5초 = ${silence(0.5).length} 샘플 · 마스터링 후 ${m.lufs.toFixed(2)} LUFS · 피크 ${m.peak.toFixed(2)} dBFS · SRT ${srtTime(3723.456)}`);
const loud = master(test.map((v) => v * 8), -10.0); // 아주 큰 목표: 피크가 상한을 넘어 리미터가 줄인다
console.log(`큰 목표(-10 LUFS): 피크 ${loud.peak.toFixed(2)} dBFS -> 상한 안`);
check(silence(0.5).length === SR / 2 && Math.abs(m.lufs + 18) < 0.5 && m.peak <= -1.0 + 1e-3
  && loud.peak <= -1.0 + 1e-3 && srtTime(3723.456) === "01:02:03,456", "쉼 = 초 x SR, LUFS 보정은 20이 아닌 10 x log10, SRT는 x1000");

goals.typescript:
// D20 · Part 6 · 목표 판정판과 품질 리포트(report.md) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d20_goals.ts
//   결과물 지표를 팀 목표값과 견주어 판정표를 만들고, 마크다운 품질 리포트를 파일로 저장한다
import { writeFileSync, readFileSync } from "node:fs";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

type Rep = { name: string; mode: string; gate_rate: number; lufs: number; peak: number; wm: number; mean_cer: number };
const MODE_LUFS: Record<string, number> = { audiobook: -18.0, announce: -16.0 };
const GOALS: [string, (r: Rep) => boolean, string][] = [
  ["게이트 통과율", (r) => r.gate_rate >= 0.8, "≥ 0.8"],
  ["음량", (r) => Math.abs(r.lufs - MODE_LUFS[r.mode]) <= 1.0, "목표 ± 1 LU"],
  ["피크", (r) => r.peak <= -1.0 + 1e-3, "≤ -1 dBFS"],
  ["워터마크", (r) => r.wm >= 0.5, "검출 1"],
  ["평균 CER", (r) => r.mean_cer <= 0.1, "≤ 0.10"],
];

const BOOK: Rep = { name: "audiobook", mode: "audiobook", gate_rate: 0.9, lufs: -18.2, peak: -1.2, wm: 1.0, mean_cer: 0.05 };
const ANN: Rep = { name: "announce", mode: "announce", gate_rate: 0.7, lufs: -19.5, peak: -0.4, wm: 0.0, mean_cer: 0.12 };
const judge: Record<string, Record<string, boolean>> = {};
for (const r of [BOOK, ANN]) judge[r.name] = Object.fromEntries(GOALS.map(([g, f]) => [g, f(r)]));
const names = Object.keys(judge);
console.log(`${"목표".padEnd(10)} ${"기준".padEnd(12)} ` + names.map((n) => n.padStart(10)).join(" "));
for (const [g, , txt] of GOALS) console.log(`${g.padEnd(10)} ${txt.padEnd(12)} ` + names.map((n) => (judge[n][g] ? "통과" : "미달").padStart(10)).join(" "));

const lines = ["# D20 TTS 품질 리포트 — 우리 팀", "", "## 목표 판정", "| 목표 | 기준 | " + names.join(" | ") + " |", "|---|---|" + "---|".repeat(names.length)];
for (const [g, , txt] of GOALS) lines.push(`| ${g} | ${txt} | ` + names.map((n) => (judge[n][g] ? "통과" : "미달")).join(" | ") + " |");
lines.push("", "## 한계와 다음 단계", "- 문장 수 · 평가자 수가 적어 순위 확정 불가", "- 고지 문구 · 워터마크 포함, 만든 소리는 수업 밖 공유 금지");
writeFileSync("report.md", lines.join("\n") + "\n", "utf-8");
const text = readFileSync("report.md", "utf-8");
const failed = Object.entries(judge["announce"]).filter(([, ok]) => !ok).map(([g]) => g);
check(Object.values(judge["audiobook"]).every(Boolean) && failed.join() === "게이트 통과율,음량,피크,워터마크,평균 CER"
  && text.includes("## 목표 판정") && text.split("미달").length - 1 === 5, "audiobook은 5개 모두 통과, announce는 5개 모두 미달이어야 해요");

rubric.python:
# D20 · Part 6 · 3분 발표 평가표: 가중 점수와 동료 평가 평균 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d20_rubric.py   (인터넷 · GPU · 마이크 불필요)
#   항목별 1~5점에 가중치(합 100)를 곱해 100점 만점으로 바꾸고, 동료 평가는 가장 높은 · 낮은 점수를 뺀 평균(절사 평균)을 쓴다
def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")

RUBRIC = {"문제와 목표": 20, "만든 것 (기술 정확성)": 25, "평가 근거 (MOS · CER · RTF)": 25, "윤리 (동의 · 고지 · 워터마크)": 15, "전달력 · 시간 (3분)": 15}


def total(scores: dict) -> float:
    """항목별 1~5점 -> 100점 만점 (점수 / 5 x 가중치의 합)"""
    return sum(scores[k] / 5 * w for k, w in RUBRIC.items())


def trimmed_mean(xs: list) -> float:
    """가장 높은 점수와 낮은 점수를 하나씩 뺀 평균 (한 사람의 극단 평가 영향을 줄임)"""
    s = sorted(xs)
    return sum(s[1:-1]) / (len(s) - 2) if len(s) > 2 else sum(s) / len(s)


team = {"문제와 목표": 4, "만든 것 (기술 정확성)": 5, "평가 근거 (MOS · CER · RTF)": 4, "윤리 (동의 · 고지 · 워터마크)": 5, "전달력 · 시간 (3분)": 3}
peers = [78.0, 82.0, 80.0, 79.0, 20.0]                     # 마지막은 장난으로 낮게 준 극단값
print("가중치 합:", sum(RUBRIC.values()), "· 팀 점수:", total(team), "· 동료 평균", sum(peers) / len(peers), "-> 절사 평균", trimmed_mean(peers))
check(sum(RUBRIC.values()) == 100 and abs(total({k: 5 for k in RUBRIC}) - 100) < 1e-9 and abs(total({k: 1 for k in RUBRIC}) - 20) < 1e-9
      and abs(total(team) - 85.0) < 1e-9 and abs(trimmed_mean(peers) - 79.0) < 1e-9, "가중치 합 100, 전부 5점이면 100점, 절사 평균은 극단값을 뺀 값")

rubric.typescript:
// D20 · Part 6 · 3분 발표 평가표: 가중 점수와 동료 평가 평균 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d20_rubric.ts
//   항목별 1~5점에 가중치(합 100)를 곱해 100점 만점으로 바꾸고, 동료 평가는 가장 높은 · 낮은 점수를 뺀 평균(절사 평균)을 쓴다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const RUBRIC: Record<string, number> = { "문제와 목표": 20, "만든 것 (기술 정확성)": 25, "평가 근거 (MOS · CER · RTF)": 25, "윤리 (동의 · 고지 · 워터마크)": 15, "전달력 · 시간 (3분)": 15 };

// 항목별 1~5점 -> 100점 만점 (점수 / 5 x 가중치의 합)
const total = (scores: Record<string, number>): number => Object.entries(RUBRIC).reduce((a, [k, w]) => a + (scores[k] / 5) * w, 0);

function trimmedMean(xs: number[]): number {
  // 가장 높은 점수와 낮은 점수를 하나씩 뺀 평균 (한 사람의 극단 평가 영향을 줄임)
  const s = [...xs].sort((a, b) => a - b);
  const use = s.length > 2 ? s.slice(1, -1) : s;
  return use.reduce((a, b) => a + b, 0) / use.length;
}

const team: Record<string, number> = { "문제와 목표": 4, "만든 것 (기술 정확성)": 5, "평가 근거 (MOS · CER · RTF)": 4, "윤리 (동의 · 고지 · 워터마크)": 5, "전달력 · 시간 (3분)": 3 };
const peers = [78.0, 82.0, 80.0, 79.0, 20.0]; // 마지막은 장난으로 낮게 준 극단값
const all = (v: number): Record<string, number> => Object.fromEntries(Object.keys(RUBRIC).map((k) => [k, v]));
console.log("가중치 합:", Object.values(RUBRIC).reduce((a, b) => a + b, 0), "· 팀 점수:", total(team), "· 동료 평균", peers.reduce((a, b) => a + b, 0) / peers.length, "-> 절사 평균", trimmedMean(peers));
check(Object.values(RUBRIC).reduce((a, b) => a + b, 0) === 100 && Math.abs(total(all(5)) - 100) < 1e-9 && Math.abs(total(all(1)) - 20) < 1e-9
  && Math.abs(total(team) - 85.0) < 1e-9 && Math.abs(trimmedMean(peers) - 79.0) < 1e-9, "가중치 합 100, 전부 5점이면 100점, 절사 평균은 극단값을 뺀 값");
